<?php $taxonomyKind=$taxonomyKind??'topic';$adminTitle=$taxonomyKind==='topic'?'مدیریت موضوعات':'مدیریت برچسب‌های مسئله'; ?>
<header><h1><?= $adminTitle ?></h1><p class="muted">موضوع حوزهٔ فعالیت است؛ برچسب مسئله دستهٔ مشترک چالش‌هاست. عنوان مسئلهٔ واقعی داخل هر تجربه ثبت می‌شود.</p></header>
<nav class="row section"><a class="secondary" href="<?= $this->h($this->url('/taxonomy?kind=topic')) ?>">مدیریت موضوعات</a><a class="secondary" href="<?= $this->h($this->url('/taxonomy?kind=issue')) ?>">مدیریت برچسب‌های مسئله</a></nav>
<form method="get" class="search section"><input type="hidden" name="r" value="/taxonomy"><input type="hidden" name="kind" value="<?= $taxonomyKind ?>"><input name="q" value="<?= $this->h($taxonomyQuery??'') ?>" placeholder="جست‌وجوی عنوان یا مسیر موضوع"><button>جست‌وجو</button></form>
<section class="card section"><h2>افزودن <?= $taxonomyKind==='topic'?'موضوع':'برچسب مسئله' ?></h2><?= str_replace('<form method="post"','<form enctype="multipart/form-data" method="post"',$this->start('/taxonomy/save')) ?><?php $term=['kind'=>$taxonomyKind];require __DIR__.'/taxonomy-fields.php'; ?></form></section>
<section class="section"><h2>موارد ثبت‌شده</h2><p class="small muted">موارد بدون استفاده قابل حذف‌اند. برای موارد متصل به تجربه یا زیرموضوع، از ادغام یا غیرفعال‌کردن استفاده کنید تا سوابق محفوظ بمانند.</p><?php foreach($rows as $term):if($term['kind']!==$taxonomyKind||(($taxonomyQuery??'')!==''&&!str_contains($term['path_title']??$term['title'],$taxonomyQuery))){continue;} ?>
<details class="taxonomy-record"><summary><strong><?= $this->h($term['path_title']??$term['title']) ?></strong><span class="tag"><?= $this->number($usage[$term['id']]??0) ?> تجربه</span><span><?= $term['active']?'فعال':'غیرفعال' ?></span></summary><?= str_replace('<form method="post"','<form enctype="multipart/form-data" method="post"',$this->start('/taxonomy/save')) ?><?php require __DIR__.'/taxonomy-fields.php'; ?></form>
<div class="taxonomy-delete"><?= $this->start('/taxonomy/delete') ?><input type="hidden" name="id" value="<?= $this->h($term['id']) ?>"><label class="check"><input type="checkbox" name="confirm_delete" value="1" required>حذف «<?= $this->h($term['title']) ?>» را تأیید می‌کنم</label><button type="submit">حذف <?= $taxonomyKind==='topic'?'موضوع':'برچسب مسئله' ?></button></form></div>
<?php if($taxonomyKind==='issue'): ?><h3>مسائل مشخص با این برچسب</h3><?php foreach($problemLinks??[] as $problem):if($problem['term_id']!==$term['id']){continue;} ?><p><a class="textlink" href="<?= $this->h($this->url('/experience/edit?id='.$problem['experience_id'])) ?>"><?= $this->h($problem['title']) ?></a><?= $this->h($problem['description']) ?></p><?php endforeach; ?><a class="textlink" href="<?= $this->h($this->url('/experiences?issue='.$term['id'])) ?>">فهرست تجربه‌های مرتبط، شامل برچسب‌های تاریخی</a><?php endif; ?></details><?php endforeach; ?></section>
<section class="card section"><h2>ادغام موارد تکراری</h2><p>پس از بررسی، مورد مبدأ غیرفعال می‌شود؛ شناسه و ارتباط‌های تاریخی حفظ و به مقصد حل می‌شوند.</p><?= $this->start('/taxonomy/merge') ?><?php foreach(['from'=>'مبدأ تکراری','into'=>'مقصد نهایی'] as $key=>$label): ?><label><?= $label ?><select name="<?= $key ?>" required><option value="">انتخاب کنید</option><?php foreach($rows as $option):if($option['kind']!==$taxonomyKind||!$option['active']){continue;} ?><option value="<?= $this->h($option['id']) ?>"><?= $this->h($option['path_title']??$option['title']) ?></option><?php endforeach; ?></select></label><?php endforeach; ?><button>ادغام با حفظ سوابق</button></form></section>
